"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[94008],{3331:(e,r,n)=>{n.d(r,{R:()=>d,x:()=>s});var i=n(36672);const t={},o=i.createContext(t);function d(e){const r=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function s(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:d(e.components),i.createElement(o.Provider,{value:r},e.children)}},69684:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>a,contentTitle:()=>s,default:()=>m,frontMatter:()=>d,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Anholdelse i SF-drab p\xe5 Bob Lee - den formodede morder arbejdede ogs\xe5 inden for teknologi","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/da/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14. april 2023","top_news":"Anholdelse i SF-drab p\xe5 Bob Lee - den formodede morder arbejdede ogs\xe5 inden for teknologi"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/da/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/da/2023/04/13"}}');var t=n(23420),o=n(3331);const d={localized_date:"14. april 2023",top_news:"Anholdelse i SF-drab p\xe5 Bob Lee - den formodede morder arbejdede ogs\xe5 inden for teknologi"},s="2023-04-14",a={},l=[{value:"Anholdelse i SF-drab p\xe5 Bob Lee - den formodede morder arbejdede ogs\xe5 inden for teknologi",id:"anholdelse-i-sf-drab-p\xe5-bob-lee---den-formodede-morder-arbejdede-ogs\xe5-inden-for-teknologi",level:2},{value:"YouTube-DL Hosting-forbud baner vejen for privatiseret censur",id:"youtube-dl-hosting-forbud-baner-vejen-for-privatiseret-censur",level:2},{value:"Kunsten at lave biler",id:"kunsten-at-lave-biler",level:2},{value:"Apple vil bruge 100 procent genbrugte kobolt i batterier inden 2025",id:"apple-vil-bruge-100-procent-genbrugte-kobolt-i-batterier-inden-2025",level:2},{value:"Vi opn\xe5ede en 6-dobbelt for\xf8gelse af Podman-starthastigheden",id:"vi-opn\xe5ede-en-6-dobbelt-for\xf8gelse-af-podman-starthastigheden",level:2},{value:"Forbedring af Tailscale via Apples \xe5bne kildekode",id:"forbedring-af-tailscale-via-apples-\xe5bne-kildekode",level:2},{value:"Animerede tegninger",id:"animerede-tegninger",level:2},{value:"Amazon CodeWhisperer, der er gratis til individuel brug, er nu generelt tilg\xe6ngelig",id:"amazon-codewhisperer-der-er-gratis-til-individuel-brug-er-nu-generelt-tilg\xe6ngelig",level:2},{value:"Google har allerede trukket seks produkter tilbage i 2023",id:"google-har-allerede-trukket-seks-produkter-tilbage-i-2023",level:2},{value:"Nvidia RTX Remix Runtime Open Source tilg\xe6ngelig nu",id:"nvidia-rtx-remix-runtime-open-source-tilg\xe6ngelig-nu",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,t.jsx)(r.h2,{id:"anholdelse-i-sf-drab-p\xe5-bob-lee---den-formodede-morder-arbejdede-ogs\xe5-inden-for-teknologi",children:"Anholdelse i SF-drab p\xe5 Bob Lee - den formodede morder arbejdede ogs\xe5 inden for teknologi"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Original"}),".\nDer er foretaget en anholdelse i forbindelse med drabet p\xe5 den teknologiske leder Bob Lee, og den formodede morder arbejdede ogs\xe5 inden for teknologibranchen og var kendt af Lee. Politiet har angiveligt fundet Lee og den mist\xe6nkte mand sammen i en bil, der er registreret i den mist\xe6nktes navn, og h\xe6vder, at der fandt en form for konfrontation sted i bilen, som muligvis fortsatte, efter at Lee var g\xe5et. D\xe6kningen af Lees d\xf8d er blevet pakket sammen med andre nylige ulykker og forbrydelser i San Francisco, selv om dette ikke n\xf8jagtigt repr\xe6senterer de fleste San Franciscaneres faktiske oplevelser."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nMordet p\xe5 en teknisk leder i San Francisco har udl\xf8st diskussioner om faktorer som hjeml\xf8shed, mental sundhed, stofmisbrug og fattigdom, der kan have f\xf8rt til forbrydelsen, men kommentatorer advarer mod at generalisere. Der er ogs\xe5 debat om brugen af statistikker i forhold til personlige anekdoter, n\xe5r man vurderer kriminalitetsrater, og der er behov for en f\xe6llesskabsinvolverende tilgang til at l\xf8se de komplekse problemer med hjeml\xf8shed, misbrug og kriminalitet. Brugerne fremh\xe6ver vigtigheden af at vurdere kriminalitetsniveauet i forhold til fattigdom i stedet for at sammenligne forskellige kulturer og ikke drage forhastede konklusioner p\xe5 baggrund af et enkelt tilf\xe6lde."]}),"\n",(0,t.jsx)(r.h2,{id:"youtube-dl-hosting-forbud-baner-vejen-for-privatiseret-censur",children:"YouTube-DL Hosting-forbud baner vejen for privatiseret censur"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Original"}),'.\nEn tysk domstol har d\xf8mt Uberspace for at v\xe6re ansvarlig for hosting af webstedet for youtube-dl - et open source-v\xe6rkt\xf8j, der g\xf8r det muligt at downloade YouTube-indhold. Uberspace advarer om, at dommen kan f\xf8re til privatiseret censur, og appellerer afg\xf8relsen, selv om retten fastslog, at Uberspace "kan holdes ansvarlig for at tvivle p\xe5 gyldigheden af en anmodning om nedtagning", selv n\xe5r det ikke var klart, at v\xe6rkt\xf8jet overtr\xe5dte loven.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nForbuddet mod YouTube-DL-hosting ses som et skub i retning af privatiseret censur, hvor RIAA og MPAA prioriterer penge og magt frem for anst\xe6ndighed. Intellektuel ejendomsrets rolle i forbindelse med begr\xe6nsning af informationsstr\xf8mmen debatteres, og der er en r\xe6kke forskellige synspunkter, herunder begr\xe6nsning af omfang og varighed. Brugerne foresl\xe5r alternativer og ford\xf8mmer afh\xe6ngigheden af GitHub, mens de diskuterer decentralisering og problemer med sikkerhed ved uklarhed i forbindelse med kopibeskyttelse."]}),"\n",(0,t.jsx)(r.h2,{id:"kunsten-at-lave-biler",children:"Kunsten at lave biler"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nThe Art of Auto Engineering er et komplet videokursus best\xe5ende af 122+ lektioner med 20 timers optagelser, der forklarer hver enkelt del af en bil i detaljer, og som d\xe6kker det grundl\xe6ggende til avanceret bilteknik. Kurset ledsages af en 200-siders h\xe5ndbog og er tilg\xe6ngeligt online eller i iOS- og Android-apps for en engangsbetaling p\xe5 $25 med livslang adgang, og er professionelt filmet i 4K-kvalitet med fuld undertekstning. Kurset er rost af seerne for sin engagerende instruktion og fremragende produktionsv\xe6rdi."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nHacker News-brugere deler erfaringer og anbefaler ressourcer til at l\xe6re om bilteknik, herunder interaktive videokurser og specifikke bilmodeller. Kommentatorer diskuterer fordelene ved at forst\xe5 bilmekanik, begr\xe6nsningerne ved udelukkende at stole p\xe5 AI og giver tips til g\xf8r-det-selv-reparationer af biler. Derudover diskuterer brugerne nytten af betalte kurser og v\xe6rkt\xf8jer, og nogle kritiserer, at der p\xe5 webstedet vises reklamer for klasser mod betaling."]}),"\n",(0,t.jsx)(r.h2,{id:"apple-vil-bruge-100-procent-genbrugte-kobolt-i-batterier-inden-2025",children:"Apple vil bruge 100 procent genbrugte kobolt i batterier inden 2025"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Original"}),".\nApple har annonceret sin plan om at bruge 100 % genbrugskobolt i alle Apple-designede batterier inden 2025, sammen med helt genbrugte sj\xe6ldne jordarter til magneter og 100 % genbrugsblik til printplader. M\xe5let er udelukkende at anvende genbrugte og fornyelige materialer, og allerede nu stammer mere end 95 % af wolfram, n\xe6sten tre fjerdedele af de sj\xe6ldne jordarter og over to tredjedele af aluminium fra 100 % genbrugsmaterialer. Apple bruger augmented reality (AR) til at styre demonteringen af enheder til genbrugspartnere og \xf8ge genvindingen af sj\xe6ldne jordarter og dermed fremme \xe6ndringer i hele industrien i retning af at reducere afh\xe6ngigheden af nyudvundne mineraler."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple annoncerede sin plan om at anvende 100 % genbrugskobolt i batterier inden 2025 og reducere plastaffaldet, men brugerne diskuterer effektiviteten af disse \xe6ndringer, og om virksomheden b\xf8r offentligg\xf8re sin genbrugsteknologi. Debatten om brugerudskiftelige batterier forts\xe6tter med argumenter om, at de er milj\xf8m\xe6ssigt negative, mens andre foresl\xe5r, at genanvendelsesmetoder og forl\xe6ngelse af holdbare produkters levetid kan l\xf8se dette problem. Apples engagement i genanvendelige materialer og en CO2-neutral forsyningsk\xe6de roses, men kritiseres for sit design og sin koboltforsyningsk\xe6de. Brugerne diskuterer levetiden for iPhones og Android-telefoner og genbrugsmetoder for batterier. Nogle brugere foresl\xe5r MagSafe-batterier som det prim\xe6re batteri til iPhones, mens andre s\xe6tter sp\xf8rgsm\xe5lstegn ved dets effektivitet."]}),"\n",(0,t.jsx)(r.h2,{id:"vi-opn\xe5ede-en-6-dobbelt-for\xf8gelse-af-podman-starthastigheden",children:"Vi opn\xe5ede en 6-dobbelt for\xf8gelse af Podman-starthastigheden"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nRed Hats containermotor, Podman, opn\xe5ede en 6-dobbelt for\xf8gelse af opstartshastigheden ved at fjerne un\xf8dvendige processer og l\xf8se mindre ineffektiviteter, der p\xe5virker kritiske applikationer som biler, hvor det er vigtigt at opstarte containere n\xe6sten i realtid. Holdet brugte transient storage og leverede workarounds for kerneproblemer, hvilket resulterede i hurtigere containeropstart. Brugen af --transient-store-indstillingen er ideel til edge-enheder, selv om mixed mode-containere ikke underst\xf8ttes."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nRed Hat's Podman ser en seksdobbelt stigning i opstartshastigheden for biler, selv om Discussion Service-brugere diskuterer overkompliceringen af moderne biler og rejser bekymringer om p\xe5lidelighed og vedligeholdelse. Diskussionen divergerer til debatter om retten til at reparere, brugen af mikroservices og containere og balancen mellem teknologiske fremskridt og praktisk anvendelighed."]}),"\n",(0,t.jsx)(r.h2,{id:"forbedring-af-tailscale-via-apples-\xe5bne-kildekode",children:"Forbedring af Tailscale via Apples \xe5bne kildekode"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),'.\nTailscale-holdet brugte Apples open source til at fejlfinding af netv\xe6rksinterface-relaterede fejl i forbindelse med deres 1.36-udgave, idet de var afh\xe6ngige af ifconfig til at bestemme den aktive netv\xe6rksgr\xe6nseflade. N\xe5r Tailscale er konfigureret til at bruge en exit node, bliver det standardruten, hvilket kr\xe6ver en rettelse for konsekvent at "binde" netv\xe6rksanmodninger til den aktive netv\xe6rksgr\xe6nseflade uden at for\xe5rsage looping-trafik. SIOCGIFDELEGATE, der er tilg\xe6ngelig via ioctl, g\xf8r det muligt at f\xe5 fat i den underliggende fysiske gr\xe6nseflade og blev implementeret i Tailscales kode til macOS og iOS.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nDiscussion Service-brugere diskuterer fordelene og udfordringerne ved software med \xe5ben og lukket kildekode i Tailscales forbedring via Apples \xe5bne kildekode. Nogle l\xf8nkunder prioriterer omd\xf8mmet af Tailscales open source-kerneprodukt, mens nogle rejser specifikke problemer med Tailscale, s\xe5som vanskeligheder med at f\xe5 adgang til netv\xe6rksandele p\xe5 Windows 11 og potentiel batteridr\xe6nning p\xe5 iOS-enheder. Diskussionen fremh\xe6ver vigtigheden af at overveje forskellige perspektiver og Tailscales voksende tr\xe6kkraft over Zerotier p\xe5 grund af dets mesh-system og kontinuerlige udrulning af nye funktioner, men der er indtjenings- og moat-problemer for nogle produktbrugere."]}),"\n",(0,t.jsx)(r.h2,{id:"animerede-tegninger",children:"Animerede tegninger"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),'.\nArkivet "Animated Drawings" p\xe5 Github implementerer den algoritme, der er beskrevet i artiklen "A Method for Automatically Animating Children\'s Drawings of the Human Figure", og giver brugerne mulighed for at skabe brugerdefinerede animationer med deres egne h\xe5ndtegnede figurer. Installationsprocessen er ligetil, og konfigurationsfiler kan \xe6ndres for at \xe6ndre forskellige indstillinger, herunder outputformater og baggrundsbilleder. Arkivet indeholder ogs\xe5 scripts og modeller til animering af personlige tegninger, og der findes en browserbaseret demo til hurtig og nem brug.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nFair Animated Drawings-projektet animerer tegninger med kode, og det findes i en browserbaseret og GitHub-version. Brugerne er interesserede i dets potentiale for forretningsid\xe9er og h\xe5ber p\xe5 en Android-app-version. Et relevant arbejde om ikke-fotorealistisk posesk\xf8n kaldet Gesture3D synes at kunne anvendes til et specifikt anvendelsestilf\xe6lde, og YC Summer 2023-ans\xf8gninger er \xe5bne."]}),"\n",(0,t.jsx)(r.h2,{id:"amazon-codewhisperer-der-er-gratis-til-individuel-brug-er-nu-generelt-tilg\xe6ngelig",children:"Amazon CodeWhisperer, der er gratis til individuel brug, er nu generelt tilg\xe6ngelig"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, en AI-kodningsf\xe6lle i realtid, er nu generelt tilg\xe6ngelig og omfatter et CodeWhisperer Individual-niveau, som alle udviklere kan bruge gratis. V\xe6rkt\xf8jet hj\xe6lper udviklere med at skrive kode hurtigt og sikkert og uden at forlade deres IDE. CodeWhisperer tilbyder forslag til generelle anvendelsestilf\xe6lde p\xe5 tv\xe6rs af en r\xe6kke sprog og kan filtrere eller markere kodeforslag, der kan ligne bestemte open source-tr\xe6ningsdata, hvilket hj\xe6lper med at reducere risikoen for at bruge potentielt forudindtaget eller fejlbeh\xe6ftet kode."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer er nu generelt tilg\xe6ngelig og underst\xf8tter flere sprog, herunder Python, Java, JavaScript, TypeScript og C#. Selv om Copilot angiveligt er bedre end CodeWhisperer, er sidstn\xe6vnte et nyttigt v\xe6rkt\xf8j, der kan f\xf8re til, at AI-genereret kode bliver normen. Derudover har Amazon lanceret CodeGuru Reviewer, et AI-v\xe6rkt\xf8j, der scanner kode for at identificere problemer og anbefale rettelser med henblik p\xe5 effektivitet og omkostningsreduktion."]}),"\n",(0,t.jsx)(r.h2,{id:"google-har-allerede-trukket-seks-produkter-tilbage-i-2023",children:"Google har allerede trukket seks produkter tilbage i 2023"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle har lukket seks produkter i de f\xf8rste fire m\xe5neder af 2023, herunder programmeringskonkurrencen Code Jam, social media-platformen Google Currents, appen Street View, wearable tech Google Jacquard, cloud gaming-tjenesten Google Stadia og den tr\xe5dl\xf8se router Google OnHub. Selv om nogle af disse produkter var over et \xe5rti gamle, har Google v\xe6ret udsat for kritik for sin vane med at afslutte popul\xe6re tjenester pludseligt."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle har afviklet seks produkter i 2023, med bekymringer om gennemsigtighed og produktm\xe6rkning og manglende st\xf8tte til mislykkede bestr\xe6belser, herunder Google Glass og Google Plus. Mens cloud-enheden vokser med en markedsandel p\xe5 10 %, er der bekymringer om kundernes og udviklernes engagement og den konto-dr\xe6bende algoritme. Brugerne diskuterer l\xf8sninger og omkostninger til forbedring af ChatGPT's n\xf8jagtighed, mens Googles ry for at opgive projekter tiltr\xe6kker kritik af produktsupport til forbrugerne."]}),"\n",(0,t.jsx)(r.h2,{id:"nvidia-rtx-remix-runtime-open-source-tilg\xe6ngelig-nu",children:"Nvidia RTX Remix Runtime Open Source tilg\xe6ngelig nu"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia har frigivet RTX Remix runtime, en open source modding-platform til remastering af klassiske DirectX 8- og 9-spil med path tracing, AI-forbedrede teksturer og brugerskabte aktiver. RTX Remix-skaberv\xe6rkt\xf8jskassen g\xf8r det muligt for moddere at tildele nye aktiver og lys i en remasteret scene og bruge AI-v\xe6rkt\xf8jer til at genopbygge udseendet af ethvert aktiv. RTX Remix-k\xf8ringstidspunktet optager derimod en spilscene, erstatter aktiver ved afspilning og indf\xf8rer RTX-teknologi, s\xe5som path tracing, DLSS 3 og Reflex i spillet."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia har frigivet sin open source RTX Remix Runtime, der giver brugerne mulighed for at spille \xe6ldre spil med ray tracing i realtid, selv om ikke alle spil vil fungere. Hacker News-brugere diskuterer betydningen af open source-drivere i forhold til propriet\xe6re drivere, Nvidias omd\xf8mme og den d\xe5rlige ydelse af RTX p\xe5 ikke-Nvidia-hardware. Brugerne spekulerer ogs\xe5 i potentiel favorisering og foresl\xe5r, at man st\xf8tter kryptovalutaudviklere, der implementerer GPU-only proof-of-work-ordninger. En bruger bem\xe6rker Remedys udvikling af Max Payne PC-spil remakes ved hj\xe6lp af Remix og diskuterer teknologiens problemer med frame pacing og stuttering."]})]})}function m(e={}){const{wrapper:r}={...(0,o.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);